        "titolo_orig": "How Serbia's government dominates the country's media",
        "testo_it": "Rapporti internazionali denunciano la crescente pressione politica sui media in Serbia.",
        "priorita": "Bassa",
        "id_gruppo": 7,
        "link": "https://www.dw.com/en/how-serbia-s-government-dominates-the-country-s-media/a-77004243?maca=en-rss-en-world-4025-rdf",
